{"path": "src/index.js", "content": "require('dotenv').config();
const express = require('express');
const morgan = require('morgan');
const mongoose = require('mongoose');
const nearbyRouter = require('./routes/nearby');

const app = express();
app.use(morgan('dev'));
app.use(express.json());

app.use('/nearby', nearbyRouter);

const PORT = process.env.PORT || 3000;
const URI = process.env.DOCUMENTDB_URI;

if (!URI) {
  console.error('DOCUMENTDB_URI is not set. Copy .env.example to .env and set DOCUMENTDB_URI');
  process.exit(1);
}

mongoose.set('strictQuery', false);

mongoose.connect(URI, { dbName: 'sample_retail_20' })
  .then(() => {
    console.log('Connected to DocumentDB cluster');
    app.listen(PORT, () => {
      console.log(`Server listening on port ${PORT}`);
    });
  })
  .catch(err => {
    console.error('Failed to connect to DocumentDB:', err);
    process.exit(1);
  });
"}

{"path": "src/models/store.js", "content": "const mongoose = require('mongoose');

const StoreSchema = new mongoose.Schema({
  name: { type: String, required: true },
  location: {
    type: { type: String, enum: ['Point'], required: true },
    coordinates: { type: [Number], required: true } // [lon, lat]
  },
  opening_hours: {
    // simple example: [{ day: 'Mon', open: '09:00', close: '17:00' }]
    type: [{ day: String, open: String, close: String }],
    default: []
  },
  stock: {
    // map of sku -> quantity
    type: Map,
    of: Number,
    default: {}
  }
}, { collection: 'stores' });

// Ensure 2dsphere index on location
StoreSchema.index({ location: '2dsphere' });

module.exports = mongoose.models.Store || mongoose.model('Store', StoreSchema);
"}

{"path": "src/routes/nearby.js", "content": "const express = require('express');
const router = express.Router();
const Store = require('../models/store');

// GET /nearby?lat=..&lon=..&radiusMeters=..
router.get('/', async (req, res) => {
  try {
    const lat = parseFloat(req.query.lat);
    const lon = parseFloat(req.query.lon);
    const radius = parseFloat(req.query.radiusMeters) || 5000; // default 5km

    if (Number.isNaN(lat) || Number.isNaN(lon)) {
      return res.status(400).json({ error: 'lat and lon query parameters are required and must be numbers' });
    }

    const pipeline = [
      {
        $geoNear: {
          near: { type: 'Point', coordinates: [lon, lat] },
          distanceField: 'distanceMeters',
          spherical: true,
          maxDistance: radius
        }
      },
      {
        $project: {
          name: 1,
          location: 1,
          opening_hours: 1,
          stock: 1,
          distanceMeters: 1
        }
      }
    ];

    const results = await Store.aggregate(pipeline).exec();
    res.json({ count: results.length, results });
  } catch (err) {
    console.error('Error in /nearby:', err);
    res.status(500).json({ error: 'internal_error' });
  }
});

module.exports = router;
"}

